  "✅ Aapne APPROVE kiya — print nikla": "✅ நீங்கள் ஒப்புதல் அளித்தீர்கள் — பிரிண்ட் வெளியே வந்தது",
  "Ek sheet par 2–16 pages — kagaz bachao": "ஒரே தாளில் 2–16 பக்கங்கள் — காகிதம் மிச்சம்",
  "⚠️ Sab band — customer ko sirf": "⚠️ அனைத்தும் அணைப்பில் — வாடிக்கையாளர் இதை மட்டுமே பார்ப்பார்",
