  "Agent code load nahi hua: %s": "ஏஜெண்ட் குறியீட்டை ஏற்ற முடியவில்லை: %s",
  "Price ₹%d se kam nahi ho sakta": "விலை ₹%d-க்குக் கீழே இருக்க முடியாது",
